def total_cents(prices):
    """Sum prices in cents, exactly."""
    return sum(prices)

def test_float_sum():
    prices = [0.1] * 600
    s = sum(prices)
    print(f"Sum of 600 * 0.1: {s}")
    print(f"int(sum): {int(s)}")
    print(f"round(sum): {round(s)}")

    # If the expected result is 60
    expected = 60
    actual = int(s)
    if actual != expected:
        print(f"FAILURE: expected {expected}, got {actual}")
    else:
        print("SUCCESS")

if __name__ == "__main__":
    test_float_sum()

def total_cents(prices):
    """Sum prices in cents, exactly."""
    return round(sum(prices))


def invoice(prices):
    return {"cents": total_cents(prices)}

